#ifndef G2D_QPU_KERNELS_V42_H
#define G2D_QPU_KERNELS_V42_H

#include <stdint.h>

/* Generated by qpuasm -v 42 -p v42_.  These declarations intentionally
 * live separately from the V3D 7.1 arrays so runtime version selection is
 * explicit and a BCM2711 can never execute a Pi 5 instruction stream. */
extern const uint64_t g2d_qpu_v42_argb_fill[];
extern const unsigned g2d_qpu_v42_argb_fill_n;
extern const uint64_t g2d_qpu_v42_argb_blit[];
extern const unsigned g2d_qpu_v42_argb_blit_n;
extern const uint64_t g2d_qpu_v42_argb_rotate[];
extern const unsigned g2d_qpu_v42_argb_rotate_n;
extern const uint64_t g2d_qpu_v42_argb_rot90[];
extern const unsigned g2d_qpu_v42_argb_rot90_n;
extern const uint64_t g2d_qpu_v42_argb_rot90_tile[];
extern const unsigned g2d_qpu_v42_argb_rot90_tile_n;
extern const uint64_t g2d_qpu_v42_argb_rot90_vpm[];
extern const unsigned g2d_qpu_v42_argb_rot90_vpm_n;
extern const uint64_t g2d_qpu_v42_argb_alpha[];
extern const unsigned g2d_qpu_v42_argb_alpha_n;
extern const uint64_t g2d_qpu_v42_argb_scale_pow2[];
extern const unsigned g2d_qpu_v42_argb_scale_pow2_n;
extern const uint64_t g2d_qpu_v42_v42_store[];
extern const unsigned g2d_qpu_v42_v42_store_n;
/* separable gaussian blur passes: radius 1 -> h3/v3, 2 -> h5/v5, 3 -> h7/v7,
 * 4 -> h9/v9 (radius > 4 is composed from these by gpu_gauss_decompose). */
extern const uint64_t g2d_qpu_v42_gauss_h3[];
extern const unsigned g2d_qpu_v42_gauss_h3_n;
extern const uint64_t g2d_qpu_v42_gauss_v3[];
extern const unsigned g2d_qpu_v42_gauss_v3_n;
extern const uint64_t g2d_qpu_v42_gauss_h5[];
extern const unsigned g2d_qpu_v42_gauss_h5_n;
extern const uint64_t g2d_qpu_v42_gauss_v5[];
extern const unsigned g2d_qpu_v42_gauss_v5_n;
extern const uint64_t g2d_qpu_v42_gauss_h7[];
extern const unsigned g2d_qpu_v42_gauss_h7_n;
extern const uint64_t g2d_qpu_v42_gauss_v7[];
extern const unsigned g2d_qpu_v42_gauss_v7_n;
extern const uint64_t g2d_qpu_v42_gauss_h9[];
extern const unsigned g2d_qpu_v42_gauss_h9_n;
extern const uint64_t g2d_qpu_v42_gauss_v9[];
extern const unsigned g2d_qpu_v42_gauss_v9_n;
/* Filled triangle (three edge half-planes, doubled + asymmetric half-pixel
 * bias): V3D 4.2 / Pi 4 only - VC4 2.1 / Pi 3 has no CSD triangle primitive
 * and declines.  Assembled from the same argb_triangle.qpu as the V3D 7.1
 * array; rf58-62 stay untouched (the v42 constant prologue reserves them). */
extern const uint64_t g2d_qpu_v42_argb_triangle[];
extern const unsigned g2d_qpu_v42_argb_triangle_n;

#endif
